```

What happens if you call an expression before its `const` line?

```js
console.log(expressed(1));
const expressed = function (n) {
  return n;
};
```

What is printed?

```js
function apply(fn, value) {
  return fn(value);
}
const triple = function (n) {
  return n * 3;
};
console.log(apply(triple, 4));
```

What is printed?

```js
const clamp = function (value, min, max) {
  if (value < min) return min;
  if (value > max) return max;
  return value;
};
console.log(clamp(5, 0, 10));
console.log(clamp(-1, 0, 10));
```
